// Package typegen turns a realm's loaded config into TypeScript types: documents, queries,
// functions, configuration, templates and roles. Everything comes from the same registry the
// server enforces; nothing is enforced at runtime from the generated files.
package typegen

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"sort"
	"strconv"
	"strings"

	"github.com/fernandezvara/backd/internal/registry"
	"github.com/fernandezvara/backd/internal/strutil"
)

// Version is the generator's version: it changes when the output format does.
const Version = "1"

// File names written by `backd types`.
const (
	TypesFile = "types.d.ts"
	InfoFile  = "realm.json"
)

// Output is what the generator produces for one realm.
type Output struct {
	Types    string   // contents of types.d.ts
	Info     Info     // contents of realm.json
	Warnings []string // things the generator couldn't express, with where
}

// Info is realm.json: what the generated types were made from, and the type-level entries
// `--diff` compares.
type Info struct {
	Generator string `json:"generator"`
	Realm     string `json:"realm"`
	// Fingerprint identifies the generated types (a hash of types.d.ts without its header):
	// what the JavaScript client sends to know whether its types are stale.
	Fingerprint string `json:"fingerprint"`
	// Config is the config directory's fingerprint, when a caller asks to record it; `backd types`
	// leaves it out, so unrelated changes to the config don't touch the committed realm.json.
	Config  string            `json:"config,omitempty"`
	Entries map[string]string `json:"entries"`
}

// Options select what to generate.
type Options struct {
	Realm    string
	Database string // empty: every database of the realm
	// Lang is the language to emit: "ts" (the default) or "dart".
	Lang string
	// Config is registry.Fingerprint of the loaded config; recorded in realm.json.
	Config string
}

// Generate produces the types of one realm.
//
// With Lang "dart" the emitted Types are Dart; the Info (entries and
// fingerprint) still comes from the TypeScript pass, so realm.json is the same
// file for every language and the stale-types check the server runs matches
// either client's fingerprint.
func Generate(reg *registry.Registry, o Options) (*Output, error) {
	rl, ok := reg.Realms[o.Realm]
	if !ok {
		return nil, fmt.Errorf("unknown realm %q", o.Realm)
	}
	if o.Database != "" {
		if _, ok := rl.Databases[o.Database]; !ok {
			return nil, fmt.Errorf("realm %q has no database %q", o.Realm, o.Database)
		}
	}
	g := &gen{entries: map[string]string{}, aliases: map[string]string{}}
	body := g.realm(rl, o)
	sum := sha256.Sum256([]byte(body))
	fp := hex.EncodeToString(sum[:])
	header := fmt.Sprintf("// Generated by `backd types` (generator %s, realm %q, types %s).\n// Do not edit: change the config and generate again.\n", Version, o.Realm, fp[:16])
	types := header + body
	if o.Lang == "dart" {
		dg := newDartGen()
		header = fmt.Sprintf("// Generated by `backd types --lang dart` (generator %s, realm %q, types %s).\n// Do not edit: change the config and generate again.\n", Version, o.Realm, fp[:16])
		types = header + dg.realm(rl, o)
		g.warnings = append(g.warnings, dg.warnings...)
	}
	slices.Sort(g.warnings)
	return &Output{
		Types:    types,
		Warnings: g.warnings,
		Info:     Info{Generator: Version, Realm: o.Realm, Fingerprint: fp, Config: o.Config, Entries: g.entries},
	}, nil
}

type gen struct {
	warnings []string
	entries  map[string]string
	aliases  map[string]string // alias → what it names, to detect collisions
}

// warn records a warning once: the same schema is converted for several types.
func (g *gen) warn(format string, args ...any) {
	m := fmt.Sprintf(format, args...)
	if !slices.Contains(g.warnings, m) {
		g.warnings = append(g.warnings, m)
	}
}

const preamble = `/** An RFC 3339 timestamp in UTC. */
export type DateTimeString = string & { readonly __backd: "date-time" };

/** What backd stores about an uploaded file. */
export interface FileDetails {
  id: string;
  name: string;
  size: number;
  type: string;
  sha256: string;
  uploaded_at: DateTimeString;
  width?: number;
  height?: number;
  versions?: Record<string, FileVersion>;
  url?: string;
  expires_at?: DateTimeString;
}

export type FileVersion =
  | { status: "pending" }
  | { status: "ready"; id: string; size: number; type: string; width: number; height: number; params: Record<string, unknown>; fingerprint: string; generated_at: DateTimeString }
  | { status: "empty" }
  | { status: "skipped"; reason: "not_an_image" | "unsupported_format" }
  | { status: "failed"; reason: "too_large" | "decode_error" };

/** The fields backd owns on every document. */
export interface Meta {
  created_at: DateTimeString;
  updated_at: DateTimeString;
  version?: number;
  owner?: string | null;
  created_by?: string;
  updated_by?: string;
  /** The organization the document belongs to, in collections that have them. */
  org?: string;
  /** The team of the organization the document belongs to, in collections that have them. */
  team?: string;
  deleted_at?: DateTimeString;
  deleted_by?: string;
  purge_at?: DateTimeString;
  /** Encrypted fields the caller may not see: they come back null, and a null here is hidden, not empty. */
  redacted?: string[];
  /** Set on a write made by a trigger run: where it sits in a chain of such writes. */
  chain?: { root: string; depth: number };
}

export type Ops<T> = { $eq?: T; $ne?: T; $in?: T[]; $nin?: T[] };
export type RangeOps<T> = { $gt?: T; $gte?: T; $lt?: T; $lte?: T; $between?: [T, T] };
export type TextOps = {
  $like?: string; $ilike?: string; $startsWith?: string; $istartsWith?: string;
  $endsWith?: string; $iendsWith?: string; $contains?: string; $icontains?: string;
};
export type NullOps = { $isNull?: boolean; $notNull?: boolean };
`

func (g *gen) realm(rl *registry.Realm, o Options) string {
	var types, tree strings.Builder
	dbs := make([]string, 0, len(rl.Databases))
	for n := range rl.Databases {
		if o.Database == "" || n == o.Database {
			dbs = append(dbs, n)
		}
	}
	sort.Strings(dbs)

	fmt.Fprintf(&tree, "export interface Realm {\n  realm: %q;\n  db: {\n", rl.Name)
	for _, dbName := range dbs {
		db := rl.Databases[dbName]
		fmt.Fprintf(&tree, "    %s: {\n      collections: {\n", member(dbName))
		cols := db.SortedCollections()
		for _, c := range cols {
			g.entries["collection "+dbName+"/"+c.Name] = ""
			doc, input, create, where, order := g.collection(&types, dbName, c)
			fmt.Fprintf(&tree, "        %s: { doc: %s; input: %s; create: %s; where: %s; order_by: %s; expand: %s; aggregate: %s; trigger: %s };\n", member(c.Name), doc, input, create, where, order, expandRefs(c), aggregateShape(c), g.triggerInput(&types, c, doc))
		}
		tree.WriteString("      };\n      functions: {\n")
		if db.Functions != nil {
			for _, name := range slices.Sorted(keys(db.Functions.Functions)) {
				fmt.Fprintf(&tree, "        %s: %s;\n", member(name), g.function(&types, dbName, db.Functions.Functions[name]))
			}
		}
		tree.WriteString("      };\n    };\n")
	}
	tree.WriteString("  };\n")

	// App configuration.
	if ac := rl.AppConfig; ac != nil {
		c := newConverter(ac.RawSchema, "Config", "_realm/config/schema.json ", g.warn)
		fmt.Fprintf(&types, "export type Config = %s;\n", c.typeOf(ac.RawSchema, ""))
		for _, name := range slices.Sorted(keys(c.defs)) {
			fmt.Fprintf(&types, "export type %s = %s;\n", name, c.defs[name])
		}
		tree.WriteString("  config: {\n    tree: Config;\n    paths: {\n")
		for _, p := range slices.Sorted(keys(ac.Paths)) {
			if !ac.Paths[p].Leaf {
				continue
			}
			t := "unknown"
			if s := schemaAt(ac.RawSchema, p); s != nil {
				t = c.typeOf(s, "/"+p)
			}
			g.entries["config "+p] = t
			fmt.Fprintf(&tree, "      %s: %s;\n", member(p), t)
		}
		tree.WriteString("    };\n  };\n")
	} else {
		tree.WriteString("  config: { tree: Record<string, never>; paths: Record<string, never> };\n")
	}

	// Templates: their data has no declared schema yet.
	tree.WriteString("  templates: {\n")
	var emailKinds, pushKinds []string
	if rl.Email != nil {
		emailKinds = rl.Email.Kinds()
	}
	if rl.Push != nil {
		pushKinds = rl.Push.Kinds()
	}
	for _, grp := range []struct {
		name  string
		kinds []string
	}{{"email", emailKinds}, {"push", pushKinds}} {
		fmt.Fprintf(&tree, "    %s: {\n", grp.name)
		for _, k := range grp.kinds {
			g.entries["template "+grp.name+" "+k] = ""
			fmt.Fprintf(&tree, "      %s: Record<string, unknown>;\n", member(k))
		}
		tree.WriteString("    };\n")
	}
	tree.WriteString("  };\n")

	roles := slices.Sorted(keys(rl.Settings.Roles))
	quoted := make([]string, len(roles))
	for i, r := range roles {
		quoted[i] = literal(r)
		g.entries["role "+r] = ""
	}
	role := "never"
	if len(quoted) > 0 {
		role = strings.Join(quoted, " | ")
	}
	fmt.Fprintf(&tree, "  roles: %s;\n", role)
	// The organization roles the realm declares, for apps that give them (only in realms with organizations).
	if o := rl.Settings.Organizations; o != nil {
		var orgRoles []string
		for _, r := range o.RoleNames() {
			orgRoles = append(orgRoles, literal(r))
			g.entries["org role "+r] = ""
		}
		fmt.Fprintf(&tree, "  org_roles: %s;\n", strings.Join(orgRoles, " | "))
		// ...and the team roles, held within one team.
		teamRoles := []string{}
		for _, r := range o.TeamRoleNames() {
			teamRoles = append(teamRoles, literal(r))
			g.entries["team role "+r] = ""
		}
		if len(teamRoles) == 0 {
			teamRoles = append(teamRoles, "never")
		}
		fmt.Fprintf(&tree, "  team_roles: %s;\n", strings.Join(teamRoles, " | "))
	}
	tree.WriteString("}\n")

	return preamble + "\n" + types.String() + "\n" + tree.String()
}

func keys[V any](m map[string]V) func(func(string) bool) {
	return func(yield func(string) bool) {
		for k := range m {
			if !yield(k) {
				return
			}
		}
	}
}

// alias returns the friendly name for a collection's type, e.g. MainNotesWhere, or "" when
// it collides with another name.
func (g *gen) alias(name, what string) string {
	if prev, ok := g.aliases[name]; ok && prev != what {
		g.warn("%s: the alias %s is already taken by %s; use the path Realm[\"db\"][...] instead", what, name, prev)
		return ""
	}
	g.aliases[name] = what
	return name
}

// collection writes a collection's types and returns the type expressions for doc, input,
// create (input, with the id a custom_id collection requires), where and order_by.
func (g *gen) collection(w *strings.Builder, db string, c *registry.Collection) (doc, input, create, where, order string) {
	prefix := strutil.Pascal(db) + strutil.Pascal(c.Name)
	where0 := db + "/" + c.Name + " schema.json "
	conv := newConverter(c.RawSchema, prefix, where0, g.warn)

	docSchema, inputSchema := fileAware(c)
	docT := conv.typeOf(docSchema, "")
	inT := conv.typeOf(inputSchema, "")

	for _, name := range slices.Sorted(keys(conv.defs)) {
		fmt.Fprintf(w, "export type %s = %s;\n", name, conv.defs[name])
	}
	pieces := []struct{ suffix, body string }{
		{"", "{ id: string; _meta: Meta } & " + wrap(docT)},
		{"Input", inT},
	}
	names := make([]string, 0, 4)
	for _, p := range pieces {
		n := g.alias(prefix+p.suffix, db+"/"+c.Name)
		if n == "" {
			names = append(names, "("+p.body+")")
			continue
		}
		fmt.Fprintf(w, "/** %s/%s */\nexport type %s = %s;\n", db, c.Name, n, p.body)
		names = append(names, n)
	}
	doc, input = names[0], names[1]
	create = input
	if cid := c.CustomID; cid != nil {
		// The client chooses the id of a document it creates: required on create only, since an
		// update names the document in the path.
		note := "the id is chosen by the client and never changes; it must match " + cid.Anchored()
		if cid.User {
			note = "the id is chosen by the client and never changes; it must be the id of the signed-in user"
		}
		body := "{ id: string } & " + wrap(inT)
		if n := g.alias(prefix+"Create", db+"/"+c.Name); n != "" {
			fmt.Fprintf(w, "/** %s/%s: %s */\nexport type %s = %s;\n", db, c.Name, strings.ReplaceAll(note, "*/", "* /"), n, body)
			create = n
		} else {
			create = "(" + body + ")"
		}
		g.entries["collection "+db+"/"+c.Name+" id"] = cid.Anchored() + " user=" + fmt.Sprint(cid.User)
	}
	g.fieldEntries(db+"/"+c.Name, c, conv)

	whereT, orderT := g.query(c)
	for i, p := range []struct{ suffix, body string }{{"Where", whereT}, {"OrderByField", orderT}} {
		n := g.alias(prefix+p.suffix, db+"/"+c.Name)
		if n == "" {
			n = "(" + strings.ReplaceAll(p.body, "Array<this>", "unknown[]") + ")"
		} else {
			fmt.Fprintf(w, "export type %s = %s;\n", n, strings.ReplaceAll(p.body, "Array<this>", "Array<"+n+">"))
		}
		if i == 0 {
			where = n
		} else {
			order = n
		}
	}
	if strings.HasPrefix(order, prefix) {
		// A sort is a field, "-field", or a comma separated list of them.
		name := prefix + "OrderBy"
		if g.alias(name, db+"/"+c.Name) != "" {
			fmt.Fprintf(w, "export type %s = %s | `${%s},${string}`;\n", name, order, order)
			order = name
		}
	}
	return
}

// fileAware returns the collection's schema twice: with file fields typed as their details
// (what reads return), and without them (what a client may write: only uploads write files).
func fileAware(c *registry.Collection) (doc, input map[string]any) {
	props, _ := c.RawSchema["properties"].(map[string]any)
	if len(c.Files) == 0 || props == nil {
		return c.RawSchema, c.RawSchema
	}
	d := map[string]any{}
	in := map[string]any{}
	for k, v := range c.RawSchema {
		d[k], in[k] = v, v
	}
	dp := map[string]any{}
	ip := map[string]any{}
	for k, v := range props {
		if f, ok := c.Files[k]; ok {
			t := "FileDetails"
			if f.Multiple {
				t = "FileDetails[]"
			}
			dp[k] = map[string]any{"x-backd-ts": t}
			continue
		}
		dp[k], ip[k] = v, v
	}
	d["properties"] = dp
	in["properties"] = ip
	if req, ok := c.RawSchema["required"].([]any); ok {
		var kept []any
		for _, r := range req {
			if n, ok := r.(string); ok {
				if _, isFile := c.Files[n]; isFile {
					continue
				}
			}
			kept = append(kept, r)
		}
		in["required"] = kept
	}
	return d, in
}

// fieldEntries records every property path of the collection with its type, for --diff.
func (g *gen) fieldEntries(where string, c *registry.Collection, conv *converter) {
	var walk func(s any, prefix string, depth int)
	walk = func(s any, prefix string, depth int) {
		m, ok := s.(map[string]any)
		if !ok || depth > 6 {
			return
		}
		props, _ := m["properties"].(map[string]any)
		required := map[string]bool{}
		if r, ok := m["required"].([]any); ok {
			for _, n := range r {
				if name, ok := n.(string); ok {
					required[name] = true
				}
			}
		}
		for _, n := range slices.Sorted(keys(props)) {
			path := n
			if prefix != "" {
				path = prefix + "." + n
			}
			t := conv.typeOf(props[n], "/properties/"+n)
			if f, ok := c.Files[path]; ok {
				t = "FileDetails"
				if f.Multiple {
					t = "FileDetails[]"
				}
			}
			if required[n] {
				t += " (required)"
			}
			g.entries["field "+where+" "+path] = t
			walk(props[n], path, depth+1)
		}
	}
	walk(c.RawSchema, "", 0)
}

func (g *gen) function(w *strings.Builder, db string, fn *registry.Function) string {
	tr := func(file, suffix string) string {
		data, err := os.ReadFile(filepath.Join(fn.Dir, file))
		if err != nil {
			return "unknown"
		}
		var raw map[string]any
		dec := json.NewDecoder(strings.NewReader(string(data)))
		dec.UseNumber()
		if err := dec.Decode(&raw); err != nil {
			return "unknown"
		}
		c := newConverter(raw, "Fn"+strutil.Pascal(db)+strutil.Pascal(fn.Name)+suffix, db+"/"+fn.Name+" "+file+" ", g.warn)
		t := c.typeOf(raw, "")
		for _, n := range slices.Sorted(keys(c.defs)) {
			fmt.Fprintf(w, "export type %s = %s;\n", n, c.defs[n])
		}
		return t
	}
	in, out := tr(registry.InputSchemaFile, "Input"), tr(registry.OutputSchemaFile, "Output")
	calls := make([]string, len(fn.Calls))
	for i, c := range fn.Calls {
		calls[i] = literal(c)
	}
	callsT := "never"
	if len(calls) > 0 {
		callsT = strings.Join(calls, " | ")
	}
	g.entries["function "+db+"/"+fn.Name+" input"] = in
	g.entries["function "+db+"/"+fn.Name+" output"] = out
	g.entries["function "+db+"/"+fn.Name+" mode"] = fn.Mode
	g.entries["function "+db+"/"+fn.Name+" internal"] = fmt.Sprint(fn.Internal)
	return fmt.Sprintf("{ input: %s; output: %s; mode: %q; internal: %t; calls: %s }", in, out, fn.Mode, fn.Internal, callsT)
}

// expandRefs renders a collection's declared references: the collection each name leads to and
// whether it holds many, which is what the types of `_expanded` are derived from.
func expandRefs(c *registry.Collection) string {
	if len(c.References) == 0 {
		return "{}"
	}
	var b strings.Builder
	b.WriteString("{ ")
	for _, name := range slices.Sorted(keys(c.References)) {
		ref := c.References[name]
		fmt.Fprintf(&b, "%s: { db: %q; collection: %q; many: %t }; ", member(name), ref.Database, ref.Collection, ref.Many)
	}
	b.WriteString("}")
	return b.String()
}

// aggregateShape renders what a collection lets an aggregation use: the fields to group by (and
// which are dates, so can be bucketed) and to measure, or never when it declares no aggregate.
func aggregateShape(c *registry.Collection) string {
	a := c.Aggregate
	if a == nil {
		return "never"
	}
	union := func(list []string) string {
		if len(list) == 0 {
			return "never"
		}
		parts := make([]string, len(list))
		for i, f := range list {
			parts[i] = strconv.Quote(f)
		}
		return strings.Join(parts, " | ")
	}
	var dates []string
	for _, f := range a.GroupBy {
		if f == "_meta.created_at" || f == "_meta.updated_at" || c.Fields[f].Date {
			dates = append(dates, f)
		}
	}
	return fmt.Sprintf("{ group_by: %s; dates: %s; metrics: %s }", union(a.GroupBy), union(dates), union(a.Metrics))
}

// triggerInput emits the input type of the functions a collection's triggers run, and returns
// its name; "never" for a collection that declares none. The documents are partial: a trigger
// only carries the bodies its `fields` asks for.
func (g *gen) triggerInput(w *strings.Builder, c *registry.Collection, doc string) string {
	if len(c.Triggers) == 0 {
		return "never"
	}
	name := doc + "TriggerInput"
	fmt.Fprintf(w, `/** What a trigger of %s runs its function with: the bodies in before and after ride only with the trigger's fields. */
export type %s = {
  id: string;
  event: "created" | "updated" | "removed";
  collection: %s;
  doc: { id: string; version: number };
  version: number;
  changed: string[];
  depth: number;
  root: string;
  at: DateTimeString;
  before?: Partial<%s> | null;
  after?: Partial<%s> | null;
  by?: string;
  truncated?: boolean;
  rescan?: string;
};

`, c.Name, name, literal(c.Name), doc, doc)
	return name
}
